class Solution {
public:
    long long minimumTotalCost(std::vector<int>& nums1, std::vector<int>& nums2) {
        long long ans = 0;
        int conflicts = 0;
        int n = nums1.size();
        std::vector<int> freq(n + 1, 0);
        int mode = 0, max_f = 0;
        for (int i = 0; i < n; ++i) {
            if (nums1[i] == nums2[i]) {
                int val = nums1[i];
                freq[val]++;
                conflicts++;
                ans += i;
                if (freq[val] > max_f) {
                    max_f = freq[val];
                    mode = val;
                }
            }
        }
        int needed = 2 * max_f - conflicts;
        if (needed <= 0) return ans;
        for (int i = 0; i < n; ++i) {
            if (nums1[i] != nums2[i] && nums1[i] != mode && nums2[i] != mode) {
                ans += i;
                needed--;
                if (needed == 0) return ans;
            }
        }
        return -1;
    }
};

