var minimumTotalCost = function(nums1, nums2) {
    let ans = 0;
    let conflicts = 0;
    const n = nums1.length;
    const freq = new Array(n + 1).fill(0);
    let mode = 0, maxF = 0;
    for (let i = 0; i < n; i++) {
        if (nums1[i] === nums2[i]) {
            const val = nums1[i];
            freq[val]++;
            conflicts++;
            ans += i;
            if (freq[val] > maxF) {
                maxF = freq[val];
                mode = val;
            }
        }
    }
    let needed = 2 * maxF - conflicts;
    if (needed <= 0) return ans;
    for (let i = 0; i < n; i++) {
        if (nums1[i] !== nums2[i] && nums1[i] !== mode && nums2[i] !== mode) {
            ans += i;
            needed--;
            if (needed === 0) return ans;
        }
